"""Long-form editorial expansion for the South Africa dossier.

All prose is a paraphrased synthesis. Source IDs point to the dossier bibliography.
The module enriches existing objects; it does not replace the curated base data.
"""

FIGURE_EXPANSIONS = [('figure-mandela', 'Nelson Rolihlahla Mandela', '1918–2013', 'Vie politique et lutte anti-apartheid', ['Né dans la famille royale thembu, Nelson Mandela étudie le droit et s’installe à Johannesburg, où il rejoint l’African National Congress. Avec Oliver Tambo, il ouvre un cabinet d’avocats qui représente de nombreux clients noirs confrontés aux lois raciales et aux restrictions administratives de l’apartheid.', 'Après la répression des campagnes de désobéissance et l’interdiction de l’ANC, Mandela participe au passage d’une partie du mouvement vers la lutte armée. Arrêté puis jugé au procès de Rivonia, il est condamné à la prison à vie en 1964 et passe vingt-sept années en détention, principalement à Robben Island puis à Pollsmoor.', 'Libéré en 1990, il joue un rôle central dans les négociations qui conduisent aux premières élections nationales au suffrage universel en 1994. Son mandat présidentiel privilégie la consolidation institutionnelle et la réconciliation, mais son héritage ne doit pas effacer le rôle collectif des syndicats, des organisations civiques, des femmes, des mouvements étudiants et des autres courants de résistance.'], ['procès de Rivonia', 'prison politique', 'négociations constitutionnelles', 'présidence 1994–1999'], ['src-saho-mandela']), ('figure-albertina-sisulu', 'Albertina Nontsikelelo Sisulu', '1918–2011', 'Organisation politique et sociale', ['Formée comme infirmière, Albertina Sisulu transforme son activité professionnelle et communautaire en base d’organisation politique. Elle rejoint la Fédération des femmes sud-africaines et participe aux campagnes contre les pass laws, qui imposaient un contrôle strict des déplacements des populations noires.', 'Son militantisme se déroule sous surveillance constante : arrestations, bannissements et détentions touchent Albertina, son mari Walter Sisulu et plusieurs membres de leur famille. Elle maintient néanmoins des réseaux d’entraide, de soins, d’éducation politique et de mobilisation locale.', 'Dans les années 1980, elle devient une figure importante du United Democratic Front, vaste coalition opposée aux structures de l’apartheid. Son parcours rappelle que la résistance ne s’est pas limitée aux dirigeants les plus médiatisés : elle reposait aussi sur un travail quotidien de quartier, de santé et d’organisation des femmes.'], ['Fédération des femmes sud-africaines', 'United Democratic Front', 'soins communautaires'], ['src-saho-albertina-sisulu']), ('figure-biko', 'Steve Biko', '1946–1977', 'Pensée politique', ['Étudiant en médecine, Steve Biko critique la domination des organisations étudiantes libérales blanches et participe à la création de la South African Students’ Organisation. Il contribue ensuite à formuler la Black Consciousness, qui insiste sur la dignité, l’autonomie politique et la libération psychologique des personnes noires.', 'Biko soutient des programmes communautaires dans les domaines de la santé, de l’éducation et de l’entraide. L’État l’interdit de déplacement et limite fortement ses activités, mais ses idées circulent dans les universités, les townships et les mouvements de jeunesse.', 'Arrêté en 1977, il meurt des suites de violences subies en détention policière. Sa mort provoque une indignation internationale et renforce la place de la Black Consciousness dans l’histoire de la résistance, sans réduire ce courant à une seule personnalité.'], ['SASO', 'Black Consciousness', 'programmes communautaires', 'mort en détention'], ['src-saho-steve-biko']), ('figure-charlotte-maxeke', 'Charlotte Makgomo Maxeke', '1871–1939', 'Éducation et droits des femmes', ['Charlotte Maxeke étudie aux États-Unis et devient l’une des premières femmes noires sud-africaines à obtenir un diplôme universitaire. À son retour, elle travaille dans l’éducation, les réseaux religieux africains et les premières organisations politiques noires.', 'Elle fonde la Bantu Women’s League, qui organise les femmes contre les pass laws et d’autres formes de contrôle administratif. Son action relie la question raciale à l’exclusion spécifique des femmes noires des institutions politiques et sociales.', 'Son parcours précède de plusieurs décennies les grandes mobilisations féminines des années 1950. Elle constitue un lien essentiel entre éducation, christianisme africain, organisation communautaire et naissance d’une politique féminine noire structurée.'], ['formation universitaire', 'Bantu Women’s League', 'campagnes contre les pass laws'], ['src-saho-charlotte-maxeke']), ('figure-shaka', 'Shaka kaSenzangakhona', 'vers 1787–1828', 'Pouvoir politique précolonial', ['Shaka devient souverain zoulou au début du XIXe siècle et consolide un pouvoir central autour de nouvelles structures militaires, politiques et tributaires. Cette transformation se déroule dans un contexte régional de concurrence, d’alliances et de recomposition des chefferies nguni.', 'Les récits sur Shaka proviennent en partie de traditions orales et de témoignages coloniaux souvent tardifs. Plusieurs descriptions de sa violence ou de ses innovations ont été amplifiées pour construire l’image d’un conquérant exceptionnel et expliquer trop simplement les bouleversements régionaux.', 'Son règne reste central pour comprendre l’histoire du royaume zoulou, mais il ne doit pas être utilisé comme cause unique des migrations et conflits du XIXe siècle. Les pressions commerciales, coloniales, écologiques et politiques régionales doivent également être prises en compte.'], ['consolidation du royaume zoulou', 'réformes militaires attribuées', 'historiographie controversée'], ['src-saho-shaka', 'src-saho-zulu-natal']), ('figure-baartman', 'Sara « Saartjie » Baartman', 'vers 1789–1815', 'Violence coloniale et mémoire', ['Sara Baartman est une femme khoekhoe emmenée du Cap vers l’Europe au début du XIXe siècle. Elle y est exhibée comme spectacle dans un contexte où le colonialisme et le racisme transforment des corps africains en objets de curiosité et de profit.', 'Après sa mort à Paris, son corps est étudié et conservé par des scientifiques européens. Ces pratiques participent à la construction d’un racisme prétendument scientifique, qui cherche à classer les êtres humains selon des hiérarchies physiques et morales.', 'Ses restes sont rapatriés en Afrique du Sud en 2002. Cette restitution devient un moment majeur des débats sur la dignité, la réparation, la propriété des restes humains et la responsabilité des musées et institutions scientifiques.'], ['exhibition humaine', 'racisme scientifique', 'restitution et mémoire'], ['src-saho-baartman']), ('figure-tutu', 'Desmond Mpilo Tutu', '1931–2021', 'Religion, droits humains et justice transitionnelle', ['D’abord enseignant puis prêtre anglican, Desmond Tutu utilise sa position religieuse pour dénoncer l’apartheid et ses effets sociaux. Il défend les sanctions internationales non violentes et insiste sur la responsabilité morale des Églises.', 'Prix Nobel de la paix en 1984, il devient l’une des voix sud-africaines les plus visibles à l’étranger. Après 1994, il préside la Commission vérité et réconciliation, qui recueille les témoignages de victimes et examine des demandes d’amnistie.', 'Son héritage associe droits humains, foi et justice transitionnelle. La Commission reste cependant débattue : elle a permis une reconnaissance publique de nombreuses violences, mais n’a pas résolu les questions de réparation, de poursuites et d’inégalités matérielles.'], ['mobilisation religieuse', 'prix Nobel de la paix', 'Commission vérité et réconciliation'], ['src-tutu-foundation', 'src-saho-nobel-laureates', 'src-trc-report-index']), ('figure-makeba', 'Miriam Makeba', '1932–2008', 'Musique, exil et diplomatie culturelle', ['Miriam Makeba commence sa carrière dans les scènes vocales et jazz sud-africaines avant d’acquérir une renommée internationale. Son interprétation de chansons en plusieurs langues contribue à faire connaître des répertoires sud-africains au-delà du continent.', 'Après avoir dénoncé l’apartheid à l’étranger, elle se voit refuser le retour dans son pays et vit plusieurs décennies en exil. Elle intervient devant les Nations Unies et associe sa carrière artistique à une mobilisation politique internationale.', 'Son parcours illustre la puissance de la musique comme archive, moyen de survie et instrument diplomatique. Il montre aussi les coûts personnels de l’exil : perte du foyer, déplacements répétés et dépendance aux contextes politiques des pays d’accueil.'], ['carrière internationale', 'exil politique', 'Nations Unies', 'diplomatie culturelle'], ['src-saho-makeba']), ('figure-oliver-tambo', 'Oliver Reginald Tambo', '1917–1993', 'Direction politique et exil', ['Oliver Tambo est enseignant, avocat et cofondateur avec Nelson Mandela d’un cabinet juridique noir à Johannesburg. Il participe à la Ligue de jeunesse de l’ANC et contribue au renouvellement stratégique du mouvement dans les années 1940 et 1950.', 'Après l’interdiction de l’ANC, il quitte l’Afrique du Sud et dirige pendant plusieurs décennies la mission extérieure de l’organisation. Il construit des réseaux diplomatiques, collecte des soutiens matériels et relie les militants en exil aux structures clandestines et militaires.', 'Son rôle est essentiel dans l’internationalisation de la lutte anti-apartheid. Il rappelle que la transition des années 1990 repose aussi sur une longue diplomatie de mouvement, menée depuis plusieurs pays africains et au-delà.'], ['ANC en exil', 'diplomatie anti-apartheid', 'réseaux internationaux'], ['src-saho-apartheid']), ('figure-walter-sisulu', 'Walter Max Ulyate Sisulu', '1912–2003', 'Organisation politique', ['Walter Sisulu rejoint l’ANC et devient l’un des principaux organisateurs de sa Ligue de jeunesse. Il joue un rôle de liaison entre générations militantes, campagnes de masse et débats stratégiques.', 'Arrêté avec d’autres dirigeants lors du procès de Rivonia, il est condamné à la prison à vie et détenu à Robben Island. Son emprisonnement devient une partie de l’histoire collective des prisonniers politiques, marquée par l’éducation mutuelle et la discipline organisationnelle.', 'Après sa libération, il participe au retour légal de l’ANC et aux préparatifs de la transition. Son héritage est souvent associé à sa capacité d’organisation et à son influence sur plusieurs générations de dirigeants.'], ['Ligue de jeunesse de l’ANC', 'procès de Rivonia', 'Robben Island'], ['src-saho-apartheid']), ('figure-lilian-ngoyi', 'Lilian Masediba Ngoyi', '1911–1980', 'Droits des femmes et organisation syndicale', ['Ouvrière du textile et syndicaliste, Lilian Ngoyi devient une dirigeante de la Fédération des femmes sud-africaines et de l’ANC Women’s League. Elle relie les luttes du travail aux campagnes contre les lois raciales.', 'En 1956, elle figure parmi les dirigeantes de la marche de milliers de femmes vers les Union Buildings à Pretoria pour protester contre l’extension des pass laws aux femmes noires.', 'Bannie et surveillée pendant de longues périodes, elle continue d’incarner une politique féminine de masse. Son parcours montre que les femmes n’étaient pas seulement des soutiens du mouvement, mais des stratèges et dirigeantes à part entière.'], ['syndicalisme', 'marche des femmes de 1956', 'pass laws'], ['src-saho-apartheid']), ('figure-robert-sobukwe', 'Robert Mangaliso Sobukwe', '1924–1978', 'Nationalisme africain', ['Enseignant et intellectuel, Robert Sobukwe quitte l’ANC pour participer à la fondation du Pan Africanist Congress. Il défend un nationalisme africain centré sur la libération politique et la restitution de la souveraineté aux populations africaines.', 'Il joue un rôle majeur dans la campagne anti-pass de 1960, au cours de laquelle la police tue des manifestants à Sharpeville. Arrêté, il reste détenu au-delà de sa peine grâce à une disposition législative spécialement conçue pour prolonger son emprisonnement.', 'Son héritage oblige à présenter la lutte anti-apartheid comme un espace pluriel, traversé par des désaccords sur la race, la classe, le nationalisme, la non-violence et les formes d’organisation.'], ['Pan Africanist Congress', 'campagne anti-pass', 'Sharpeville'], ['src-saho-apartheid']), ('figure-ruth-first', 'Ruth First', '1925–1982', 'Journalisme, recherche et exil', ['Journaliste et militante communiste, Ruth First enquête sur le travail migrant, l’exploitation minière, le nationalisme et les réseaux de pouvoir de l’apartheid. Son travail combine reportage, analyse politique et recherche universitaire.', 'Détenue et soumise à l’isolement, elle quitte ensuite l’Afrique du Sud et poursuit son activité en exil. Elle enseigne et travaille notamment au Mozambique, où elle étudie les transformations sociales postcoloniales.', 'Elle est assassinée en 1982 par une lettre piégée envoyée par les services de sécurité sud-africains. Son parcours illustre le ciblage transnational des opposants et l’importance des intellectuels dans la production d’outils de compréhension de l’apartheid.'], ['journalisme d’enquête', 'exil', 'assassinat politique'], ['src-saho-apartheid']), ('figure-chris-hani', 'Chris Hani', '1942–1993', 'Lutte armée et transition', ['Chris Hani rejoint l’ANC et le Parti communiste sud-africain, puis devient un commandant important d’Umkhonto we Sizwe. Son expérience inclut l’exil, la formation militaire et les débats internes sur la stratégie de libération.', 'À son retour légal en Afrique du Sud, il acquiert une forte popularité, en particulier parmi les jeunes et les travailleurs. Il défend la négociation tout en maintenant une critique des inégalités économiques.', 'Son assassinat en avril 1993 provoque une crise nationale et menace le processus de négociation. La mobilisation qui suit accélère la fixation d’une date pour les élections de 1994.'], ['Umkhonto we Sizwe', 'Parti communiste sud-africain', 'assassinat de 1993'], ['src-saho-apartheid', 'src-saho-elections']), ('figure-sol-plaatje', 'Solomon Tshekisho Plaatje', '1876–1932', 'Littérature, journalisme et politique', ['Sol Plaatje travaille comme interprète, journaliste, écrivain et traducteur. Polyglotte, il participe à la création du South African Native National Congress, futur ANC, et documente les effets des politiques foncières sur les populations noires.', 'Son ouvrage consacré au Natives Land Act de 1913 décrit la dépossession et les déplacements provoqués par la loi. Il voyage à l’étranger pour défendre les revendications politiques africaines et utilise la presse comme espace de mobilisation.', 'Son œuvre littéraire et politique en fait une figure centrale de l’histoire intellectuelle sud-africaine. Elle relie langue, traduction, témoignage et construction d’une citoyenneté refusée par l’Union sud-africaine.'], ['journalisme', 'fondation de l’ANC', 'Natives Land Act', 'traduction'], ['src-saho-union-democracy']), ('figure-nadine-gordimer', 'Nadine Gordimer', '1923–2014', 'Littérature', ['Nadine Gordimer construit une œuvre romanesque et critique attentive aux relations raciales, aux privilèges blancs et aux transformations politiques de l’Afrique du Sud. Ses récits observent la manière dont les structures de l’apartheid traversent la vie intime.', 'Elle soutient des écrivains et organisations opposés au régime et plusieurs de ses ouvrages sont censurés. Son engagement ne dispense pas de discuter la position sociale depuis laquelle elle écrit ni les débats sur la représentation des expériences noires.', 'Lauréate du prix Nobel de littérature en 1991, elle demeure une figure importante de la littérature mondiale et de l’histoire des rapports entre création artistique, censure et responsabilité politique.'], ['roman', 'censure', 'prix Nobel de littérature'], ['src-saho-nobel-laureates']), ('figure-jm-coetzee', 'J. M. Coetzee', 'né en 1940', 'Littérature', ['J. M. Coetzee est romancier, essayiste et universitaire. Ses œuvres interrogent la violence, l’autorité, le langage, la domination coloniale et la responsabilité morale sans se limiter au réalisme historique direct.', 'Plusieurs romans utilisent des situations allégoriques ou des voix narratives instables pour questionner la manière dont le pouvoir produit ses propres récits. Cette esthétique a suscité des lectures très diverses dans le contexte sud-africain.', 'Il reçoit le prix Nobel de littérature en 2003. Son œuvre fait partie des débats sur la littérature de l’apartheid et de l’après-apartheid, ainsi que sur les rapports entre universalité littéraire et histoire locale.'], ['roman', 'allégorie politique', 'prix Nobel de littérature'], ['src-saho-nobel-laureates']), ('figure-hugh-masekela', 'Hugh Ramapolo Masekela', '1939–2018', 'Musique et exil', ['Trompettiste, compositeur et chanteur, Hugh Masekela se forme dans les scènes jazz sud-africaines des années 1950. Après le massacre de Sharpeville, il quitte le pays et développe une carrière internationale.', 'Sa musique combine jazz, traditions sud-africaines et commentaires sur le travail migrant, l’exil et la répression. Des chansons comme celles consacrées aux mineurs ou à Nelson Mandela deviennent des repères de la culture anti-apartheid.', 'Son retour après la transition démocratique souligne le rôle des artistes exilés dans la circulation internationale des histoires sud-africaines. Il contribue aussi à la formation et à la visibilité de nouvelles générations de musiciens.'], ['jazz sud-africain', 'exil', 'musique anti-apartheid'], ['src-sa-yearbook-arts']), ('figure-brenda-fassie', 'Brenda Nokuzola Fassie', '1964–2004', 'Musique populaire', ['Brenda Fassie grandit au Cap puis s’installe à Johannesburg, où elle devient l’une des voix majeures de la pop sud-africaine. Sa carrière traverse les transformations de la musique urbaine des années 1980 et 1990.', 'Ses chansons abordent l’amour, la vie quotidienne et parfois directement la politique. Sa popularité repose autant sur sa voix et son énergie scénique que sur sa capacité à représenter une modernité noire urbaine.', 'Sa vie publique, marquée par l’attention médiatique et des difficultés personnelles, ne doit pas réduire l’importance de son œuvre. Elle demeure une référence majeure pour la musique populaire sud-africaine et africaine.'], ['pop sud-africaine', 'culture urbaine', 'transition démocratique'], ['src-sa-yearbook-arts']), ('figure-allan-cormack', 'Allan MacLeod Cormack', '1924–1998', 'Science et médecine', ['Né à Johannesburg et formé en Afrique du Sud, Allan Cormack travaille sur les méthodes mathématiques permettant de reconstruire des images internes à partir de mesures de rayonnement.', 'Ses recherches fournissent une base théorique essentielle au développement de la tomographie assistée par ordinateur. L’innovation résulte ensuite de la convergence entre mathématiques, physique, électronique et pratique clinique.', 'Il partage le prix Nobel de physiologie ou médecine en 1979. Son parcours montre comment des recherches théoriques peuvent transformer profondément le diagnostic médical.'], ['mathématiques appliquées', 'tomodensitométrie', 'prix Nobel de médecine'], ['src-nobel-cormack']), ('figure-sydney-brenner', 'Sydney Brenner', '1927–2019', 'Biologie moléculaire', ['Né à Germiston, Sydney Brenner étudie la médecine avant de s’orienter vers la recherche en biologie moléculaire. Il participe aux travaux qui clarifient la relation entre information génétique et synthèse des protéines.', 'Il contribue à faire du nématode Caenorhabditis elegans un organisme modèle majeur pour l’étude du développement et de la mort cellulaire programmée.', 'Le prix Nobel de physiologie ou médecine lui est attribué en 2002 avec Robert Horvitz et John Sulston. Son héritage tient autant à ses découvertes qu’à la création de systèmes expérimentaux utilisés par des milliers de chercheurs.'], ['code génétique', 'C. elegans', 'biologie du développement', 'prix Nobel'], ['src-nobel-brenner']), ('figure-max-theiler', 'Max Theiler', '1899–1972', 'Virologie et santé publique', ['Né à Pretoria, Max Theiler étudie la médecine et mène ensuite ses recherches aux États-Unis. Il travaille sur la transmission et l’atténuation du virus de la fièvre jaune.', 'Ses travaux contribuent au développement du vaccin 17D, qui devient un outil majeur de prévention de la fièvre jaune. Cette histoire doit être replacée dans celle des laboratoires, des campagnes sanitaires et de la production vaccinale internationale.', 'Il reçoit le prix Nobel de physiologie ou médecine en 1951. Son parcours illustre la dimension transnationale de la science et des politiques de santé publique.'], ['virologie', 'vaccin contre la fièvre jaune', 'prix Nobel'], ['src-nobel-theiler'])]

PEOPLE_EXPANSIONS = {'people-san': ['Le terme San regroupe plusieurs communautés d’Afrique australe qui possèdent des langues, des territoires et des histoires distinctes. Il ne désigne ni une population uniforme ni une seule langue. Les classifications coloniales ont souvent effacé cette diversité.', 'Des communautés san ont développé des connaissances fines des paysages, des plantes, des animaux et des cycles saisonniers. L’art rupestre, les récits et les pratiques de guérison constituent des archives importantes, mais ils doivent être interprétés avec les communautés concernées.', 'La colonisation, la clôture des terres, la chasse commerciale et les politiques de conservation ont entraîné dépossession et marginalisation. Aujourd’hui, les enjeux comprennent les droits fonciers, la revitalisation linguistique et le contrôle de la représentation culturelle.'], 'people-khoikhoi': ['Les Khoekhoe regroupent historiquement diverses communautés pastorales de l’ouest et du sud de l’Afrique australe. Leurs économies reposaient notamment sur l’élevage, les échanges et la mobilité saisonnière, avec des organisations politiques variables.', 'L’établissement colonial au Cap provoque guerres, épidémies, perte des pâturages et incorporation forcée dans l’économie coloniale. Les identités précises sont souvent absorbées dans des catégories administratives plus larges.', 'Les mouvements contemporains de reconnaissance khoekhoe portent sur la langue, la terre, les autorités traditionnelles et la mémoire. Le terme composite « Khoisan » peut être utile dans certains contextes politiques, mais ne doit pas supprimer les différences entre Khoekhoe et San.'], 'people-nguni': ['Les communautés de langues nguni comprennent notamment des groupes xhosa, zoulous, swazi et ndebele. Il s’agit d’un regroupement linguistique et historique, non d’un peuple unique.', 'Leurs histoires comprennent des formations politiques, migrations, alliances et conflits distincts. Les frontières nationales actuelles coupent plusieurs réseaux familiaux et culturels plus anciens.', 'L’urbanisation, le travail migrant et les médias ont transformé les pratiques linguistiques et culturelles. Les langues nguni demeurent centrales dans l’éducation, la musique, la littérature, la politique et la vie quotidienne.'], 'people-sotho-tswana': ['Les communautés sotho-tswana comprennent notamment Basotho, Batswana, Bapedi et d’autres groupes liés par des langues proches mais par des histoires politiques différentes.', 'Elles ont construit des établissements, chefferies et royaumes avant les frontières modernes. Des sites comme Kaditshwene montrent l’importance de l’urbanisation, de la métallurgie et des réseaux commerciaux régionaux.', 'Les liens contemporains traversent l’Afrique du Sud, le Lesotho et le Botswana. Les identités nationales, locales et linguistiques se superposent sans se confondre.'], 'people-venda': ['Les communautés vhaVenda sont principalement associées au nord du Limpopo, mais leurs histoires sont liées à des réseaux régionaux dépassant les frontières actuelles.', 'Le patrimoine venda comprend des traditions politiques, des paysages sacrés, des arts, des pratiques musicales et des systèmes de transmission initiatique. Le lac Fundudzi occupe une place importante dans plusieurs récits et pratiques.', 'Les transformations contemporaines incluent urbanisation, christianisation, migrations professionnelles et revendications de protection du patrimoine vivant.'], 'people-tsonga': ['Les communautés tsonga sont présentes en Afrique du Sud, au Mozambique, en Eswatini et au Zimbabwe. Le terme recouvre plusieurs histoires locales et trajectoires de mobilité.', 'Les réseaux commerciaux, le travail migrant et les frontières coloniales ont contribué à la dispersion et à la recomposition des communautés. Le xitsonga est aujourd’hui une langue officielle sud-africaine.', 'Musique, danse, oralité et pratiques familiales continuent d’évoluer dans des contextes ruraux, urbains et transnationaux.'], 'people-indian-sa': ['Les Sud-Africains d’origine indienne descendent de trajectoires différentes. À partir de 1860, des travailleurs sous contrat sont transportés vers le Natal, tandis que des commerçants et artisans migrent aussi de manière plus libre.', 'Ces communautés développent des institutions religieuses, éducatives, commerciales et politiques. Elles subissent des discriminations coloniales puis les classifications et déplacements imposés par l’apartheid.', 'La diversité linguistique, religieuse et sociale demeure importante. Les cultures alimentaires, littéraires, musicales et politiques sud-africaines ont été profondément façonnées par ces histoires.'], 'people-coloured': ['La catégorie « Coloured » est une construction historique et administrative qui regroupe des personnes aux ascendances et identités très diverses, notamment khoekhoe, san, africaines, européennes, malgaches, sud-asiatiques et sud-est asiatiques.', 'L’esclavage au Cap, la colonisation et les classifications raciales ont progressivement produit cette catégorie. Sous l’apartheid, elle détermine le logement, l’éducation, le travail et les droits politiques.', 'Aujourd’hui, certaines personnes revendiquent cette identité, tandis que d’autres la contestent ou la combinent avec des identités khoekhoe, musulmanes, africaines ou locales. Elle ne doit jamais être présentée comme un groupe biologique homogène.']}

SOCIETY_EXPANSIONS = {'Citoyenneté et ordre constitutionnel': ['La citoyenneté démocratique issue de 1994 repose sur l’égalité juridique et le suffrage universel. La Constitution de 1996 affirme que l’État doit respecter, protéger, promouvoir et réaliser les droits fondamentaux.', 'La citoyenneté vécue reste toutefois inégale. L’accès aux documents, aux services municipaux, à la justice et à la participation publique dépend des ressources, de la localisation et des capacités administratives.', 'Les débats contemporains portent sur la confiance institutionnelle, la responsabilité des élus, la corruption, la qualité des services et la capacité des citoyens à obtenir réparation.'], 'Diversité et identités': ['L’Afrique du Sud reconnaît douze langues officielles et rassemble des histoires religieuses, culturelles et migratoires multiples. Les identités peuvent être linguistiques, régionales, familiales, professionnelles, politiques et religieuses à la fois.', 'Les catégories raciales héritées de l’apartheid restent utilisées dans certaines statistiques et politiques de réparation. Elles peuvent aider à mesurer des inégalités structurelles, mais elles ne décrivent pas entièrement les identités vécues.', 'Une présentation responsable doit donc distinguer les catégories administratives, les auto-identifications et les histoires communautaires.'], 'Inégalités persistantes': ['L’Afrique du Sud demeure marquée par de très fortes inégalités de revenus, de patrimoine et d’accès aux opportunités. Ces écarts sont liés à la dépossession foncière, à la ségrégation urbaine, à l’éducation différenciée et à l’organisation raciale du travail.', 'Les politiques publiques postérieures à 1994 ont élargi l’accès au logement, à l’électricité, à l’éducation et aux transferts sociaux. Les progrès sont néanmoins inégaux et les infrastructures se dégradent dans plusieurs territoires.', 'La richesse moyenne ou les indicateurs nationaux masquent des écarts importants entre quartiers, municipalités, provinces, sexes et générations.'], 'Urbanisation et territoires': ['Les métropoles comme Johannesburg, Le Cap, Durban et Pretoria concentrent emplois, universités, transports et services spécialisés. Elles attirent des migrations internes et régionales tout en reproduisant une forte ségrégation résidentielle.', 'Les townships et périphéries urbaines ne sont pas de simples espaces de pauvreté : ils possèdent des économies, cultures, mobilisations et formes d’innovation propres. Les distances imposées par l’apartheid continuent cependant d’alourdir les coûts de transport et l’accès à l’emploi.', 'Les zones rurales connaissent des réalités diverses, entre agriculture commerciale, terres communautaires, anciens bantoustans, tourisme et dépendance aux revenus migratoires.']}

CULTURE_EXPANSIONS = {'Musique et cultures sonores': ['Les musiques sud-africaines se développent dans des contextes ruraux, urbains, religieux, miniers et diasporiques. Le marabi, le jazz, le mbaqanga, l’isicathamiya, le kwaito, le gqom et l’amapiano appartiennent à des périodes et réseaux différents.', 'Le travail migrant et les hostels ont joué un rôle majeur dans la circulation des répertoires. Les musiciens ont adapté des instruments, langues et formes chorales à des environnements urbains ségrégués.', 'Pendant l’apartheid, la musique sert à la fois de divertissement, d’archive sociale et d’outil de mobilisation. Les industries culturelles contemporaines prolongent ces circulations à l’échelle mondiale.'], 'Danse, théâtre et performance': ['La danse et le théâtre sud-africains réunissent pratiques cérémonielles, spectacles populaires, compétitions communautaires et création professionnelle. Les significations varient selon le contexte et ne peuvent être réduites à une représentation touristique.', 'Le théâtre de protestation développe des formes adaptées à la censure, aux tournées et aux espaces communautaires. Il met en scène le travail, la prison, les déplacements forcés et les contradictions de la société urbaine.', 'Depuis 1994, les artistes interrogent aussi la mémoire, le genre, la xénophobie, les inégalités et les identités post-apartheid.'], 'Arts visuels, artisanat et design': ['L’art rupestre san, les peintures murales ndebele, le perlage, la céramique, la vannerie et la sculpture sont liés à des usages sociaux et rituels précis. Leur présentation comme simples motifs décoratifs efface souvent leurs propriétaires et leurs significations.', 'La photographie documentaire joue un rôle majeur dans la représentation de la vie sous l’apartheid, des mobilisations et des transformations urbaines. Les archives photographiques doivent être contextualisées : qui photographie, pour quel public et avec quel pouvoir de diffusion ?', 'Les arts contemporains mobilisent installations, vidéo, mode et design pour revisiter la mémoire coloniale, les corps, la terre et les frontières sociales.'], 'Oralité, littérature et langues de création': ['La littérature sud-africaine circule entre oralité, presse, poésie, théâtre et roman. Les langues africaines, l’afrikaans et l’anglais possèdent des histoires éditoriales inégales, façonnées par l’école, la mission, la censure et les marchés du livre.', 'Les izibongo et autres formes de poésie de louange peuvent conserver généalogie, commentaire politique et mémoire publique. Leur performance varie selon le public et le moment historique.', 'Les écrivains contemporains abordent l’apartheid, la migration, la violence, la sexualité, la mémoire familiale et les nouvelles inégalités, souvent dans plusieurs langues.'], 'Cuisines et cultures alimentaires': ['Les cuisines sud-africaines sont issues d’histoires pastorales, agricoles, coloniales et migratoires. Les céréales, légumineuses, viandes, poissons, épices et méthodes de conservation diffèrent fortement selon les régions.', 'L’esclavage et les circulations de l’océan Indien ont profondément marqué les cuisines du Cap. Au Natal, l’engagisme et les migrations indiennes ont contribué à des traditions culinaires distinctes, dont les currys de Durban.', 'Le braai et le shisa nyama sont des pratiques sociales autant que culinaires. Leur présentation comme emblèmes nationaux doit laisser place aux différences de classe, de région et de communauté.'], 'Architecture et paysages habités': ['L’architecture sud-africaine comprend sites archéologiques, établissements de pierre, habitats vernaculaires, missions, bâtiments coloniaux, infrastructures minières, townships et projets contemporains.', 'L’espace bâti constitue une archive du pouvoir. Les lois de ségrégation et de déplacement ont séparé lieux de résidence, de travail et de consommation, produisant des distances qui structurent encore les villes.', 'Les débats actuels concernent la restitution des terres, la conservation des bâtiments coloniaux, la transformation des monuments et l’accès au logement bien situé.']}

ADDITIONAL_SOURCES = [
{'id': 'src-tutu-foundation', 'category': 'A', 'title': 'Desmond Tutu biography and legacy', 'publisher': 'Desmond & Leah Tutu Legacy Foundation', 'year': 2026, 'url': 'https://www.tutu.org.za/'},
{'id': 'src-trc-report-index', 'category': 'A', 'title': 'Truth and Reconciliation Commission Final Report', 'publisher': 'Department of Justice and Constitutional Development', 'year': 1998, 'url': 'https://www.justice.gov.za/trc/report/index.htm'},
{'id': 'src-sa-yearbook-arts', 'category': 'A', 'title': 'South Africa Yearbook: Arts and Culture', 'publisher': 'Government Communication and Information System', 'year': 2023, 'url': 'https://www.gcis.gov.za/content/resourcecentre/sa-info/yearbook'},
]

def apply_editorial_expansion(dossier):
    existing = {item.get('id') or item.get('name'): item for item in dossier.get('figures', [])}
    enriched = []
    for fid, name, period, category, paragraphs, highlights, sources in FIGURE_EXPANSIONS:
        item = dict(existing.get(fid) or existing.get(name) or {})
        item.update({
            'id': fid, 'name': name, 'period': period, 'birth': period.split('–')[0] if '–' in period else period,
            'field': category, 'category': category, 'reason': paragraphs[0], 'summary': paragraphs[0],
            'biography': paragraphs, 'highlights': highlights, 'legacy': paragraphs[-1],
            'status': item.get('status','ready'), 'sources': sources,
        })
        enriched.append(item)
    dossier['figures'] = enriched

    for item in dossier.get('peoples', []):
        key = item.get('id')
        if key in PEOPLE_EXPANSIONS:
            item['paragraphs'] = PEOPLE_EXPANSIONS[key]
            item['history'] = PEOPLE_EXPANSIONS[key][0]
            item['contemporary'] = PEOPLE_EXPANSIONS[key][-1]

    for item in dossier.get('society', {}).get('themes', []):
        if item.get('title') in SOCIETY_EXPANSIONS:
            item['paragraphs'] = SOCIETY_EXPANSIONS[item['title']]
            item['context'] = SOCIETY_EXPANSIONS[item['title']][1]

    for item in dossier.get('culture', []):
        title = item.get('topic') or item.get('title')
        if title in CULTURE_EXPANSIONS:
            item['paragraphs'] = CULTURE_EXPANSIONS[title]
            item['context'] = CULTURE_EXPANSIONS[title][1]

    source_ids = {s.get('id') for s in dossier.get('sources', [])}
    dossier.setdefault('sources', []).extend(s for s in ADDITIONAL_SOURCES if s['id'] not in source_ids)
    dossier['editorial_depth'] = {
        'edition': 'South Africa long-form editorial expansion v1',
        'figure_biographies': len(FIGURE_EXPANSIONS),
        'people_chapters': len(PEOPLE_EXPANSIONS),
        'society_chapters': len(SOCIETY_EXPANSIONS),
        'culture_chapters': len(CULTURE_EXPANSIONS),
        'method': 'Paraphrased synthesis with source links; no verbatim copying.'
    }
    return dossier
